-- Trim mandate_summary and timeline_intro back toward the original
-- deep-dive design length after they drifted progressively longer with
-- each recent country addition (flagged by Dan: Hungary's timeline_intro
-- had reached 191 words / 1283 characters, versus a ~20-35 word / ~150-280
-- character norm for the first 30+ countries added to this tracker).
--
-- Retargets mandate_summary to roughly 90-100 words and timeline_intro to
-- roughly 50-60 words for the six countries that had grown past that norm:
-- Czech Republic, Argentina, Colombia, Philippines, Taiwan, and Hungary.
-- All four languages (en/es/de/fr) updated to match. No facts were cut --
-- these are condensed rewrites preserving every date, resolution number,
-- and figure from the original text, just without the extra elaboration.
--
-- Pure content UPDATE against deep_dive_page_translations -- no schema
-- change, no static-file change, no worker redeploy needed.

-- Czech Republic
UPDATE deep_dive_page_translations SET mandate_summary = 'The Czech Republic has required public bodies to accept EN 16931-compliant e-invoices since 1 October 2016 (Act No. 134/2016 Coll.); issuance by suppliers remains voluntary, and no domestic B2B mandate has been proposed. The real story is EET 2.0, a revived real-time B2C sales-reporting regime -- not an invoicing mandate -- which has passed the Chamber of Deputies and awaits Senate and presidential approval, with a confirmed 1 January 2027 effective date, a CZK 1,000,000 small-business exemption, and penalties up to CZK 500,000. The EU''s ViDA cross-border B2B floor applies from 1 July 2030 regardless.', timeline_intro = 'The Czech Republic completed a modest, receiving-only B2G e-invoicing rollout by October 2016 and has never proposed a domestic B2B mandate. The country''s real news is EET 2.0 -- real-time B2C sales reporting, not invoicing -- already through the Chamber of Deputies, confirmed effective 1 January 2027. ViDA''s cross-border floor still applies from 1 July 2030.' WHERE lang = 'en' AND country_id = (SELECT id FROM countries WHERE name_en = 'Czech Republic');
UPDATE deep_dive_page_translations SET mandate_summary = 'La República Checa exige a los organismos públicos aceptar facturas electrónicas conformes con EN 16931 desde el 1 de octubre de 2016 (Ley n.º 134/2016 Coll.); la emisión por parte de los proveedores sigue siendo voluntaria, y nunca se ha propuesto un mandato nacional B2B. La verdadera novedad es el EET 2.0, un régimen reactivado de reporte en tiempo real de ventas B2C -- no un mandato de facturación -- que ya ha sido aprobado por la Cámara de Diputados y espera la aprobación del Senado y la firma presidencial, con una fecha de entrada en vigor confirmada del 1 de enero de 2027, una exención para pequeñas empresas de hasta 1.000.000 CZK y sanciones de hasta 500.000 CZK. El suelo transfronterizo B2B de ViDA de la UE se aplica de todos modos desde el 1 de julio de 2030.', timeline_intro = 'La República Checa completó un modesto despliegue de facturación electrónica B2G, solo de recepción, para octubre de 2016, y nunca ha propuesto un mandato nacional B2B. La verdadera novedad del país es el EET 2.0 -- reporte en tiempo real de ventas B2C, no facturación -- ya aprobado por la Cámara de Diputados, con entrada en vigor confirmada el 1 de enero de 2027. El suelo transfronterizo de ViDA sigue aplicándose desde el 1 de julio de 2030.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Czech Republic');
UPDATE deep_dive_page_translations SET mandate_summary = 'Tschechien verpflichtet öffentliche Stellen seit dem 1. Oktober 2016 (Gesetz Nr. 134/2016 Coll.) zur Annahme EN-16931-konformer E-Rechnungen; die Ausstellung durch Lieferanten bleibt freiwillig, und eine inländische B2B-Pflicht wurde nie vorgeschlagen. Die eigentliche Neuigkeit ist EET 2.0, ein wiederbelebtes Echtzeit-Meldesystem für B2C-Verkäufe -- keine Rechnungspflicht --, das das Abgeordnetenhaus bereits passiert hat und auf die Zustimmung von Senat und Präsident wartet, mit bestätigtem Inkrafttreten am 1. Januar 2027, einer Befreiung für Kleinunternehmen bis 1.000.000 CZK und Strafen bis 500.000 CZK. Die grenzüberschreitende ViDA-Untergrenze der EU gilt unabhängig davon ab dem 1. Juli 2030.', timeline_intro = 'Tschechien schloss bis Oktober 2016 einen bescheidenen, reinen Empfangs-Rollout für B2G-E-Rechnungen ab und hat nie eine inländische B2B-Pflicht vorgeschlagen. Die eigentliche Neuigkeit des Landes ist EET 2.0 -- Echtzeitmeldung von B2C-Verkäufen, keine Rechnungsstellung -- bereits durch das Abgeordnetenhaus, mit bestätigtem Inkrafttreten am 1. Januar 2027. Die grenzüberschreitende ViDA-Untergrenze gilt weiterhin ab dem 1. Juli 2030.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Czech Republic');
UPDATE deep_dive_page_translations SET mandate_summary = 'La République tchèque exige que les organismes publics acceptent des factures électroniques conformes à l''EN 16931 depuis le 1er octobre 2016 (loi n° 134/2016 Coll.) ; l''émission par les fournisseurs reste volontaire, et aucune obligation nationale B2B n''a été proposée. La vraie nouveauté est l''EET 2.0, un régime relancé de déclaration en temps réel des ventes B2C -- non une obligation de facturation -- déjà adopté par la Chambre des députés et en attente de l''approbation du Sénat et de la signature présidentielle, avec une date d''entrée en vigueur confirmée au 1er janvier 2027, une exemption pour petites entreprises jusqu''à 1 000 000 CZK et des sanctions pouvant atteindre 500 000 CZK. Le plancher transfrontalier B2B de ViDA de l''UE s''applique de toute façon à partir du 1er juillet 2030.', timeline_intro = 'La République tchèque a achevé d''ici octobre 2016 un déploiement modeste, uniquement en réception, de la facturation électronique B2G, et n''a jamais proposé d''obligation nationale B2B. La vraie nouveauté du pays est l''EET 2.0 -- déclaration en temps réel des ventes B2C, non la facturation -- déjà adopté par la Chambre des députés, avec une entrée en vigueur confirmée au 1er janvier 2027. Le plancher transfrontalier de ViDA continue de s''appliquer à partir du 1er juillet 2030.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Czech Republic');

-- Argentina
UPDATE deep_dive_page_translations SET mandate_summary = 'Argentina''s e-invoicing regime began voluntary in 2003, became mandatory for VAT-registered taxpayers under RG 3749/2015, and went effectively universal -- covering every monotributista and final-consumer sale -- from 1 April 2019 (RG 4290/2018). The system runs on real-time clearance: ARCA (renamed from AFIP in 2024) validates each invoice and assigns a CAE before delivery, without which the invoice has no fiscal validity. Since going universal, updates have continued: RG 5616/2024 added itemized VAT/FX disclosure, RG 5705/2025 introduced pre-filled VAT returns, and RG 5824/2026 (1 July 2026) extends the mandate to new sectors. Non-compliance carries a real 2-6 day closure penalty.', timeline_intro = 'Argentina pioneered regional e-invoicing, moving from voluntary (2003) to mandatory for VAT-registered taxpayers (RG 3749/2015), then effectively universal from 1 April 2019 (RG 4290/2018). Rather than settling, the system keeps evolving: the 2024 AFIP-to-ARCA rebrand, 2025''s itemized VAT/FX disclosure and pre-filled returns, and a further sector expansion effective 1 July 2026 (RG 5824/2026).' WHERE lang = 'en' AND country_id = (SELECT id FROM countries WHERE name_en = 'Argentina');
UPDATE deep_dive_page_translations SET mandate_summary = 'El régimen de facturación electrónica de Argentina comenzó como voluntario en 2003, se volvió obligatorio para los responsables inscriptos en IVA bajo la RG 3749/2015 y se volvió prácticamente universal -- cubriendo a todo monotributista y venta a consumidor final -- desde el 1 de abril de 2019 (RG 4290/2018). El sistema funciona mediante clearance en tiempo real: ARCA (renombrada de AFIP en 2024) valida cada factura y asigna un CAE antes de la entrega, sin el cual la factura no tiene validez fiscal. Desde que se volvió universal, las actualizaciones han continuado: la RG 5616/2024 añadió el detalle de IVA/tipo de cambio, la RG 5705/2025 introdujo declaraciones de IVA prellenadas, y la RG 5824/2026 (1 de julio de 2026) extiende el mandato a nuevos sectores. El incumplimiento conlleva una sanción real de clausura de 2 a 6 días.', timeline_intro = 'Argentina fue pionera en la facturación electrónica regional, pasando de voluntaria (2003) a obligatoria para los responsables inscriptos en IVA (RG 3749/2015), y luego prácticamente universal desde el 1 de abril de 2019 (RG 4290/2018). En lugar de estabilizarse, el sistema sigue evolucionando: el cambio de nombre de AFIP a ARCA en 2024, el detalle de IVA/tipo de cambio y las declaraciones prellenadas de 2025, y una nueva ampliación sectorial vigente desde el 1 de julio de 2026 (RG 5824/2026).' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Argentina');
UPDATE deep_dive_page_translations SET mandate_summary = 'Argentiniens E-Rechnungsregime begann 2003 freiwillig, wurde für umsatzsteuerlich registrierte Steuerpflichtige unter der RG 3749/2015 verpflichtend und ab dem 1. April 2019 praktisch universell -- einschließlich jedes Monotributista und jedes Verkaufs an Endverbraucher (RG 4290/2018). Das System arbeitet mit Echtzeit-Clearing: ARCA (2024 von AFIP umbenannt) validiert jede Rechnung und vergibt einen CAE vor der Auslieferung, ohne den die Rechnung keine steuerliche Gültigkeit hat. Seit Erreichen der Universalität geht die Entwicklung weiter: Die RG 5616/2024 fügte eine aufgeschlüsselte USt./Wechselkurs-Angabe hinzu, die RG 5705/2025 führte vorausgefüllte USt.-Erklärungen ein, und die RG 5824/2026 (1. Juli 2026) weitet das Mandat auf neue Sektoren aus. Nichteinhaltung zieht eine echte Schließungsstrafe von 2-6 Tagen nach sich.', timeline_intro = 'Argentinien war Vorreiter der regionalen E-Rechnungsstellung und wechselte von freiwillig (2003) zu verpflichtend für umsatzsteuerlich registrierte Steuerpflichtige (RG 3749/2015) und dann ab dem 1. April 2019 praktisch universell (RG 4290/2018). Statt sich zu stabilisieren, entwickelt sich das System weiter: die Umbenennung von AFIP zu ARCA 2024, die aufgeschlüsselte USt./Wechselkurs-Angabe und vorausgefüllte Erklärungen 2025, sowie eine weitere Sektorenausweitung ab dem 1. Juli 2026 (RG 5824/2026).' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Argentina');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le régime de facturation électronique de l''Argentine a débuté volontairement en 2003, est devenu obligatoire pour les assujettis inscrits à la TVA en vertu de la RG 3749/2015, puis pratiquement universel -- couvrant chaque monotributista et vente aux consommateurs finaux -- à partir du 1er avril 2019 (RG 4290/2018). Le système fonctionne par clearance en temps réel : l''ARCA (renommée depuis l''AFIP en 2024) valide chaque facture et attribue un CAE avant la remise, sans lequel la facture n''a aucune validité fiscale. Depuis qu''il est devenu universel, les mises à jour se sont poursuivies : la RG 5616/2024 a ajouté le détail TVA/taux de change, la RG 5705/2025 a introduit des déclarations de TVA pré-remplies, et la RG 5824/2026 (1er juillet 2026) étend le mandat à de nouveaux secteurs. Le non-respect entraîne une véritable sanction de fermeture de 2 à 6 jours.', timeline_intro = 'L''Argentine a fait figure de pionnière de la facturation électronique régionale, passant du volontaire (2003) à l''obligatoire pour les assujettis inscrits à la TVA (RG 3749/2015), puis à un système pratiquement universel à partir du 1er avril 2019 (RG 4290/2018). Plutôt que de se stabiliser, le système continue d''évoluer : le changement de nom d''AFIP à ARCA en 2024, le détail TVA/taux de change et les déclarations pré-remplies de 2025, et une nouvelle extension sectorielle en vigueur depuis le 1er juillet 2026 (RG 5824/2026).' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Argentina');

-- Colombia
UPDATE deep_dive_page_translations SET mandate_summary = 'Colombia''s DIAN runs a real-time pre-validation clearance system: every Factura Electrónica de Venta must receive a CUFE from DIAN before reaching the buyer, becoming legally valid only on approval. The mandate began with large taxpayers under Resolution 000010/2018 and became effectively universal on 1 November 2020 (Resolution 000042/2020). DIAN has since extended coverage to "documentos equivalentes electrónicos" -- POS receipts, utility bills, transport tickets -- completed by 1 November 2024 (Resolution 000165/2023), refined buyer-data rules (Resolution 000202/2025), and in 2026 let businesses voluntarily regularize past gaps (Resolution 000011/2026). Non-compliance carries a 1%-of-value fine and 3-10 day closure.', timeline_intro = 'Colombia recognized e-invoices legally as early as 1995 and built its clearance system from 2015, with the first mandatory wave (large taxpayers) landing 1 September 2018 and the mandate going effectively universal on 1 November 2020. DIAN has since broadened coverage to new document types and refined the system procedurally through 2025 and 2026.' WHERE lang = 'en' AND country_id = (SELECT id FROM countries WHERE name_en = 'Colombia');
UPDATE deep_dive_page_translations SET mandate_summary = 'La DIAN colombiana opera un sistema de clearance con validación previa en tiempo real: toda Factura Electrónica de Venta debe recibir un CUFE de la DIAN antes de llegar al comprador, adquiriendo validez legal solo tras su aprobación. El mandato comenzó con los grandes contribuyentes bajo la Resolución 000010 de 2018 y se volvió prácticamente universal el 1 de noviembre de 2020 (Resolución 000042 de 2020). Desde entonces, la DIAN ha ampliado la cobertura a los "documentos equivalentes electrónicos" -- tickets POS, facturas de servicios públicos, boletos de transporte -- completada el 1 de noviembre de 2024 (Resolución 000165 de 2023), ha refinado las reglas de datos del comprador (Resolución 000202 de 2025) y en 2026 permitió a las empresas regularizar voluntariamente vacíos previos (Resolución 000011 de 2026). El incumplimiento conlleva una multa del 1% del valor y clausura de 3 a 10 días.', timeline_intro = 'Colombia reconoció legalmente la factura electrónica ya en 1995 y construyó su sistema de clearance a partir de 2015, con la primera ola obligatoria (grandes contribuyentes) llegando el 1 de septiembre de 2018 y el mandato volviéndose prácticamente universal el 1 de noviembre de 2020. Desde entonces, la DIAN ha ampliado la cobertura a nuevos tipos de documentos y ha refinado el sistema a nivel procedimental durante 2025 y 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Colombia');
UPDATE deep_dive_page_translations SET mandate_summary = 'Die kolumbianische DIAN betreibt ein Echtzeit-Vorabvalidierungssystem: Jede Factura Electrónica de Venta muss von der DIAN einen CUFE erhalten, bevor sie den Käufer erreicht, und wird erst nach Genehmigung rechtsgültig. Das Mandat begann mit Großsteuerpflichtigen nach der Resolution 000010/2018 und wurde am 1. November 2020 praktisch universell (Resolution 000042/2020). Die DIAN hat die Abdeckung seither auf "documentos equivalentes electrónicos" -- Kassenbons, Versorgungsrechnungen, Fahrscheine -- ausgeweitet, abgeschlossen bis zum 1. November 2024 (Resolution 000165/2023), die Regeln zu Käuferdaten verfeinert (Resolution 000202/2025) und 2026 Unternehmen erlaubt, frühere Lücken freiwillig zu regularisieren (Resolution 000011/2026). Nichteinhaltung zieht eine Geldbuße von 1% des Werts und eine Schließung von 3-10 Tagen nach sich.', timeline_intro = 'Kolumbien erkannte die elektronische Rechnung bereits 1995 gesetzlich an und baute sein Clearing-System ab 2015 auf, wobei die erste Pflichtwelle (Großsteuerpflichtige) am 1. September 2018 einsetzte und das Mandat am 1. November 2020 praktisch universell wurde. Die DIAN hat die Abdeckung seither auf neue Dokumenttypen ausgeweitet und das System 2025 und 2026 verfahrenstechnisch verfeinert.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Colombia');
UPDATE deep_dive_page_translations SET mandate_summary = 'La DIAN colombienne exploite un système de clearance avec validation préalable en temps réel : chaque Factura Electrónica de Venta doit recevoir un CUFE de la DIAN avant de parvenir à l''acheteur, n''acquérant une validité légale qu''après approbation. Le mandat a débuté avec les grands contribuables en vertu de la résolution 000010 de 2018 et est devenu pratiquement universel le 1er novembre 2020 (résolution 000042 de 2020). La DIAN a depuis étendu la couverture aux "documentos equivalentes electrónicos" -- tickets de caisse, factures de services publics, billets de transport -- achevée le 1er novembre 2024 (résolution 000165 de 2023), a affiné les règles relatives aux données acheteur (résolution 000202 de 2025) et a permis en 2026 aux entreprises de régulariser volontairement des lacunes antérieures (résolution 000011 de 2026). Le non-respect entraîne une amende de 1 % de la valeur et une fermeture de 3 à 10 jours.', timeline_intro = 'La Colombie a reconnu légalement la facture électronique dès 1995 et a construit son système de clearance à partir de 2015, la première vague obligatoire (grands contribuables) arrivant le 1er septembre 2018 et le mandat devenant pratiquement universel le 1er novembre 2020. La DIAN a depuis élargi la couverture à de nouveaux types de documents et affiné le système sur le plan procédural en 2025 et 2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Colombia');

-- Philippines
UPDATE deep_dive_page_translations SET mandate_summary = 'The Philippines'' BIR runs a post-issuance reporting model under its Electronic Invoicing/Receipting System: an invoice is valid once it reaches the buyer, with sales-data transmission to the BIR a separate duty. The legal basis dates to 2018''s TRAIN Law, but the mandate has a documented history of slipping -- a 2022 pilot paused for roughly two years, and Revenue Regulations No. 26-2025 has already pushed the current Phase 1 deadline to 31 December 2026, covering Large Taxpayers, e-commerce businesses, exporters, and CAS/POS users. Non-compliance carries fines, imprisonment, and possible permanent closure after 180 days.', timeline_intro = 'The legal basis dates to 2018''s TRAIN Law, authorizing e-invoicing and near-real-time sales reporting for large taxpayers. A 2022 pilot ("LT100") paused for roughly two years before RR 11-2025 resumed and expanded the mandate in 2025. That deadline itself slipped again: RR 26-2025 (October 2025) pushed Phase 1 to 31 December 2026.' WHERE lang = 'en' AND country_id = (SELECT id FROM countries WHERE name_en = 'Philippines');
UPDATE deep_dive_page_translations SET mandate_summary = 'El BIR de Filipinas opera un modelo de reporte posterior a la emisión bajo su Sistema de Facturación/Recibos Electrónicos: una factura es válida en cuanto llega al comprador, siendo la transmisión de datos de ventas al BIR una obligación separada. La base legal se remonta a la Ley TRAIN de 2018, pero el mandato tiene un historial documentado de retrasos -- un piloto de 2022 se pausó durante aproximadamente dos años, y el Reglamento de Rentas N.º 26-2025 ya ha extendido el plazo actual de la Fase 1 al 31 de diciembre de 2026, cubriendo a Grandes Contribuyentes, empresas de comercio electrónico, exportadores y usuarios de CAS/POS. El incumplimiento conlleva multas, prisión y posible clausura permanente tras 180 días.', timeline_intro = 'La base legal se remonta a la Ley TRAIN de 2018, que autorizó la facturación electrónica y el reporte de ventas casi en tiempo real para grandes contribuyentes. Un piloto de 2022 ("LT100") se pausó durante aproximadamente dos años antes de que el RR 11-2025 retomara y ampliara el mandato en 2025. Ese plazo volvió a extenderse: el RR 26-2025 (octubre de 2025) llevó la Fase 1 al 31 de diciembre de 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Philippines');
UPDATE deep_dive_page_translations SET mandate_summary = 'Die philippinische Steuerbehörde BIR betreibt unter ihrem Electronic Invoicing/Receipting System ein Meldemodell nach Ausstellung: Eine Rechnung ist gültig, sobald sie den Käufer erreicht, während die Übermittlung der Verkaufsdaten an das BIR eine separate Pflicht ist. Die Rechtsgrundlage reicht bis zum TRAIN-Gesetz von 2018 zurück, doch das Mandat hat eine dokumentierte Geschichte von Verzögerungen -- ein Pilotprojekt von 2022 pausierte rund zwei Jahre, und die Revenue Regulations No. 26-2025 hat die aktuelle Frist für Phase 1 bereits auf den 31. Dezember 2026 verschoben, für Großsteuerpflichtige, E-Commerce-Unternehmen, Exporteure und CAS/POS-Nutzer. Nichteinhaltung zieht Geldbußen, Freiheitsstrafen und eine mögliche endgültige Schließung nach 180 Tagen nach sich.', timeline_intro = 'Die Rechtsgrundlage reicht bis zum TRAIN-Gesetz von 2018 zurück, das elektronische Rechnungsstellung und eine nahezu in Echtzeit erfolgende Meldung von Verkaufsdaten für Großsteuerpflichtige ermöglichte. Ein Pilotprojekt von 2022 ("LT100") pausierte rund zwei Jahre, bevor die RR 11-2025 das Mandat 2025 wieder aufnahm und erweiterte. Diese Frist wurde selbst erneut verschoben: Die RR 26-2025 (Oktober 2025) verschob Phase 1 auf den 31. Dezember 2026.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Philippines');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le BIR des Philippines exploite un modèle de déclaration post-émission dans le cadre de son Electronic Invoicing/Receipting System : une facture est valide dès qu''elle atteint l''acheteur, la transmission des données de vente au BIR étant une obligation distincte. Le fondement juridique remonte à la loi TRAIN de 2018, mais le mandat a un historique documenté de retards -- un projet pilote de 2022 a été suspendu pendant environ deux ans, et le règlement fiscal n° 26-2025 a déjà repoussé l''échéance actuelle de la Phase 1 au 31 décembre 2026, couvrant les grands contribuables, les entreprises de commerce électronique, les exportateurs et les utilisateurs de CAS/POS. Le non-respect entraîne amendes, emprisonnement et fermeture définitive possible après 180 jours.', timeline_intro = 'Le fondement juridique remonte à la loi TRAIN de 2018, autorisant la facturation électronique et la déclaration des ventes quasi en temps réel pour les grands contribuables. Un projet pilote de 2022 ("LT100") a été suspendu pendant environ deux ans avant que le RR 11-2025 ne relance et n''élargisse le mandat en 2025. Cette échéance a elle-même de nouveau été repoussée : le RR 26-2025 (octobre 2025) a porté la Phase 1 au 31 décembre 2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Philippines');

-- Taiwan
UPDATE deep_dive_page_translations SET mandate_summary = 'Taiwan''s Ministry of Finance operates eGUI as a post-issuance transmission model: an invoice is valid once it reaches the buyer, with transmission to the MOF''s E-Invoice Platform a separate, timed obligation. The mandate became universal on 1 January 2021, covering every business-tax-registered entity for B2B and B2C alike. A Business Tax Act amendment (3 September 2024) set 7-day (B2B) and 2-day (B2C) transmission deadlines, backed by TWD 1,500-15,000 fines. Since 1 January 2026, the MIG 4.0 XML format is the only valid eGUI format. In September 2025, Taiwan also became a Peppol Authority for cross-border invoicing.', timeline_intro = 'Taiwan''s eGUI system built up in stages: cross-border VAT/eGUI obligations for foreign digital providers from 1 May 2017, the universal domestic mandate from 1 January 2021, formalized transmission deadlines and penalties via a 2024 Business Tax Act amendment, and MIG 4.0 becoming the sole valid XML format once the legacy transition period closed 31 December 2025.' WHERE lang = 'en' AND country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan');
UPDATE deep_dive_page_translations SET mandate_summary = 'El Ministerio de Finanzas de Taiwán opera el eGUI como un modelo de transmisión posterior a la emisión: una factura es válida en cuanto llega al comprador, y la transmisión a la Plataforma de Facturación Electrónica del MOF es una obligación aparte y con plazo. El mandato se volvió universal el 1 de enero de 2021, cubriendo a toda entidad registrada a efectos del impuesto empresarial, tanto B2B como B2C. Una enmienda a la Ley del Impuesto Empresarial (3 de septiembre de 2024) fijó plazos de transmisión de 7 días (B2B) y 2 días (B2C), respaldados por multas de TWD 1.500-15.000. Desde el 1 de enero de 2026, el formato XML MIG 4.0 es el único formato eGUI válido. En septiembre de 2025, Taiwán se convirtió además en una Autoridad Peppol para la facturación transfronteriza.', timeline_intro = 'El sistema eGUI de Taiwán se construyó por etapas: obligaciones transfronterizas de IVA/eGUI para proveedores digitales extranjeros desde el 1 de mayo de 2017, el mandato nacional universal desde el 1 de enero de 2021, plazos de transmisión y sanciones formalizados mediante una enmienda a la Ley del Impuesto Empresarial en 2024, y el MIG 4.0 convirtiéndose en el único formato XML válido una vez que el período de transición de los formatos anteriores finalizó el 31 de diciembre de 2025.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan');
UPDATE deep_dive_page_translations SET mandate_summary = 'Taiwans Finanzministerium betreibt eGUI als Übermittlungsmodell nach Rechnungsausstellung: Eine Rechnung ist gültig, sobald sie den Käufer erreicht, während die Übermittlung an die E-Invoice-Plattform des MOF eine separate, fristgebundene Pflicht ist. Das Mandat wurde am 1. Januar 2021 universell und erfasst jedes umsatzsteuerlich registrierte Unternehmen für B2B wie B2C. Eine Änderung des Umsatzsteuergesetzes (3. September 2024) legte Übermittlungsfristen von 7 Tagen (B2B) und 2 Tagen (B2C) fest, unterlegt mit Bußgeldern von TWD 1.500-15.000. Seit dem 1. Januar 2026 ist das MIG-4.0-XML-Format das einzig gültige eGUI-Format. Im September 2025 wurde Taiwan zudem eine Peppol Authority für die grenzüberschreitende Rechnungsstellung.', timeline_intro = 'Taiwans eGUI-System entstand stufenweise: grenzüberschreitende USt-/eGUI-Pflichten für ausländische digitale Anbieter ab dem 1. Mai 2017, das universelle inländische Mandat ab dem 1. Januar 2021, formalisierte Übermittlungsfristen und Sanktionen durch eine Änderung des Umsatzsteuergesetzes 2024, und MIG 4.0 als einzig gültiges XML-Format, nachdem die Übergangsfrist für die Altformate am 31. Dezember 2025 endete.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le ministère des Finances de Taïwan exploite l''eGUI selon un modèle de transmission postérieure à l''émission : une facture est valide dès qu''elle parvient à l''acheteur, la transmission à la plateforme de facturation électronique du MOF constituant une obligation distincte et soumise à délai. Le mandat est devenu universel le 1er janvier 2021, couvrant toute entité enregistrée à la taxe professionnelle, B2B comme B2C. Un amendement à la loi sur la taxe professionnelle (3 septembre 2024) a fixé des délais de transmission de 7 jours (B2B) et 2 jours (B2C), appuyés par des amendes de 1 500 à 15 000 TWD. Depuis le 1er janvier 2026, le format XML MIG 4.0 est le seul format eGUI valide. En septembre 2025, Taïwan est également devenue une Autorité Peppol pour la facturation transfrontalière.', timeline_intro = 'Le système eGUI de Taïwan s''est construit par étapes : obligations transfrontalières de TVA/eGUI pour les fournisseurs numériques étrangers à partir du 1er mai 2017, le mandat national universel à partir du 1er janvier 2021, des délais de transmission et sanctions formalisés par un amendement à la loi sur la taxe professionnelle en 2024, et le MIG 4.0 devenant le seul format XML valide une fois close la période de transition des anciens formats, le 31 décembre 2025.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Taiwan');

-- Hungary
UPDATE deep_dive_page_translations SET mandate_summary = 'Hungary''s NAV has operated Real-Time Invoice Reporting (RTIR) since 1 July 2018, now covering essentially every VAT-relevant invoice -- but RTIR is a transaction-DATA reporting duty, not an e-invoicing format mandate; the underlying invoice can remain paper or PDF. That changed narrowly from 1 July 2025, when energy and water utility suppliers became required to actually issue electronic invoices for B2B supplies -- Hungary''s first real e-invoicing mandate, though sector-specific. From 1 September 2026, mandatory reporting expands to receipts. A comprehensive future framework remains proposed, not enacted. The EU''s ViDA sets a confirmed cross-border floor from 1 July 2030 regardless.', timeline_intro = 'Hungary''s RTIR system is one of Europe''s most mature transaction-reporting regimes, reaching near-universal scope by 2021 -- but it reports invoice DATA, not the document format. That changed narrowly from 1 July 2025 for energy/water B2B suppliers, Hungary''s first genuine e-invoicing mandate. A comprehensive future framework remains proposed; ViDA''s cross-border floor applies from 1 July 2030 regardless.' WHERE lang = 'en' AND country_id = (SELECT id FROM countries WHERE name_en = 'Hungary');
UPDATE deep_dive_page_translations SET mandate_summary = 'La NAV de Hungría opera el Reporte de Facturas en Tiempo Real (RTIR) desde el 1 de julio de 2018, que ahora cubre prácticamente toda factura relevante a efectos de IVA -- pero RTIR es una obligación de reporte de DATOS de la transacción, no un mandato de formato de facturación electrónica; la factura subyacente puede seguir siendo en papel o PDF. Eso cambió de forma limitada a partir del 1 de julio de 2025, cuando los proveedores de energía y agua pasaron a estar obligados a emitir realmente facturas electrónicas para los suministros B2B -- el primer mandato real de facturación electrónica de Hungría, aunque específico de un sector. A partir del 1 de septiembre de 2026, el reporte obligatorio se amplía a los recibos. Un marco integral futuro sigue siendo una propuesta, no una norma promulgada. La directiva ViDA de la UE fija de todos modos un suelo transfronterizo confirmado desde el 1 de julio de 2030.', timeline_intro = 'El sistema RTIR de Hungría es uno de los regímenes de reporte de transacciones más maduros de Europa, alcanzando un alcance casi universal para 2021 -- pero reporta los DATOS de la factura, no el formato del documento. Eso cambió de forma limitada a partir del 1 de julio de 2025 para los proveedores B2B de energía/agua, el primer mandato genuino de facturación electrónica de Hungría. Un marco integral futuro sigue siendo una propuesta; el suelo transfronterizo de ViDA se aplica de todos modos desde el 1 de julio de 2030.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Hungary');
UPDATE deep_dive_page_translations SET mandate_summary = 'Ungarns NAV betreibt seit dem 1. Juli 2018 die Echtzeit-Rechnungsmeldung (RTIR), die inzwischen praktisch jede umsatzsteuerlich relevante Rechnung erfasst -- doch RTIR ist eine Pflicht zur Meldung von Transaktions-DATEN, keine E-Rechnungs-Formatpflicht; die zugrunde liegende Rechnung kann weiterhin auf Papier oder als PDF vorliegen. Das änderte sich begrenzt ab dem 1. Juli 2025, als Strom- und Wasserversorger verpflichtet wurden, für B2B-Lieferungen tatsächlich elektronische Rechnungen auszustellen -- Ungarns erste echte E-Rechnungspflicht, wenn auch sektorspezifisch. Ab dem 1. September 2026 weitet sich die Meldepflicht auf Belege aus. Ein umfassendes künftiges Rahmenwerk bleibt ein Vorschlag, kein geltendes Recht. Die ViDA-Richtlinie der EU setzt unabhängig davon ab dem 1. Juli 2030 eine bestätigte grenzüberschreitende Untergrenze.', timeline_intro = 'Ungarns RTIR-System ist eines der ausgereiftesten Transaktionsmeldesysteme Europas und erreichte bis 2021 nahezu universellen Umfang -- meldet aber Rechnungs-DATEN, nicht das Dokumentformat. Das änderte sich begrenzt ab dem 1. Juli 2025 für Strom-/Wasser-B2B-Lieferanten, Ungarns erste echte E-Rechnungspflicht. Ein umfassendes künftiges Rahmenwerk bleibt ein Vorschlag; die ViDA-Untergrenze gilt unabhängig davon ab dem 1. Juli 2030.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Hungary');
UPDATE deep_dive_page_translations SET mandate_summary = 'La NAV hongroise exploite la déclaration des factures en temps réel (RTIR) depuis le 1er juillet 2018, couvrant désormais pratiquement toute facture pertinente au regard de la TVA -- mais RTIR est une obligation de déclaration de DONNÉES de transaction, non une obligation de format de facturation électronique ; la facture sous-jacente peut rester au format papier ou PDF. Cela a changé de manière limitée à compter du 1er juillet 2025, lorsque les fournisseurs d''énergie et d''eau ont été tenus d''émettre effectivement des factures électroniques pour les fournitures B2B -- la première véritable obligation de facturation électronique en Hongrie, bien que sectorielle. À compter du 1er septembre 2026, la déclaration obligatoire s''étend aux reçus. Un cadre global futur reste une proposition, non une règle promulguée. La directive ViDA de l''UE fixe de toute façon un plancher transfrontalier confirmé à compter du 1er juillet 2030.', timeline_intro = 'Le système RTIR de la Hongrie est l''un des régimes de déclaration des transactions les plus matures d''Europe, atteignant une portée quasi universelle dès 2021 -- mais il déclare les DONNÉES de la facture, non le format du document. Cela a changé de manière limitée à compter du 1er juillet 2025 pour les fournisseurs B2B d''énergie/eau, la première véritable obligation de facturation électronique en Hongrie. Un cadre global futur reste une proposition ; le plancher transfrontalier de ViDA s''applique de toute façon à compter du 1er juillet 2030.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Hungary');
